@* Displays the current theme in the header — works in static and interactive contexts *@
<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0078d4");">
    @ThemeLabel
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeLabel => Theme?.Mode switch
    {
        ThemeMode.Dark => "🌙 Dark",
        ThemeMode.System => "💻 System",
        _ => "☀️ Light"
    };
}

@using sv_512acb35885a49518d3271e439ff0608.Services
@inject CascadingValueSource<ThemeInfo> ThemeSource

<div class="theme-switcher">
    <button @onclick="CycleTheme" title="Toggle theme">
        @switch (Theme?.Mode)
        {
            case ThemeMode.Dark:
                <span>🌙</span>
                break;
            case ThemeMode.System:
                <span>💻</span>
                break;
            default:
                <span>☀️</span>
                break;
        }
    </button>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task CycleTheme()
    {
        var current = Theme ?? ThemeInfo.Default;
        var nextMode = current.Mode switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            _ => ThemeMode.Light
        };
        await ThemeSource.NotifyChangedAsync(current with { Mode = nextMode });
    }
}

